const p = $('Params').first().json;
const cur = ($input.first().json.body && $input.first().json.body.keys) || [];
const byId = {}; for (const k of cur) { byId[k.key_id] = k; }
const out = []; const skipped = [];
for (const want of p.keys) {
  if (p.only_key_ids.length && p.only_key_ids.indexOf(want.key_id) === -1) { continue; }
  const k = byId[want.key_id];
  if (!k || k.is_archived) { skipped.push({ key_id: want.key_id, why: 'missing or archived' }); continue; }
  const have = k.tags || [];
  const add = want.tags.filter(t => have.indexOf(t) === -1);
  const row = { key_id: want.key_id };
  if (add.length) { row.tags = add; row.merge_tags = true; }
  if (want.description && !(k.description || '').trim()) { row.description = want.description; }
  else if (want.description) { skipped.push({ key_id: want.key_id, why: 'description not empty, kept' }); }
  if (row.tags || row.description) { out.push(row); }
}
if (!out.length) { return []; }
return [{ json: { body: { keys: out }, skipped: skipped, before: cur.map(k => ({ key_id: k.key_id, tags: k.tags, description: k.description })) } }];

const sent = $('Build').first().json.body.keys;
const before = $('Build').first().json.before;
const res = ($input.first().json.body && $input.first().json.body.keys) || [];
const errors = ($input.first().json.body && $input.first().json.body.errors) || [];
const rep = [];
for (const s of sent) {
  const r = res.find(x => x.key_id === s.key_id) || {};
  const b = before.find(x => x.key_id === s.key_id) || { tags: [] };
  const tags = r.tags || [];
  rep.push({ key_id: s.key_id, name: r.key_name && r.key_name.web,
    new_tags_ok: (s.tags || []).every(t => tags.indexOf(t) !== -1),
    old_tags_kept: (b.tags || []).every(t => tags.indexOf(t) !== -1),
    description_ok: s.description ? r.description === s.description : null, tags: tags });
}
return [{ json: { summary_marker: 1, status: $input.first().json.statusCode, errors: errors, report: rep, skipped: $('Build').first().json.skipped } }];

const p = $('Params').first().json;
const s = $input.first().json.screenshot;
const have = s.key_ids || [];
const add = p.screenshot_add_key_ids.filter(id => have.indexOf(id) === -1);
if (!add.length) { return []; }
return [{ json: { before: have, add: add, body: { key_ids: have.concat(add) } } }];

const b = $('Build Shot').first().json;
const s = ($input.first().json.screenshot) || {};
const after = s.key_ids || [];
return [{ json: { shot_marker: 1, added_ok: b.add.every(id => after.indexOf(id) !== -1), old_kept: b.before.every(id => after.indexOf(id) !== -1), before_count: b.before.length, after_count: after.length, title: s.title, raw_error: $input.first().json.error || null } }];
